mapper.select:
select p.id, p.student_id, p.amount, p.category, p.reason, p.created_at, p.idempotency_key,
       exists(select 1 from point_ledger r where r.idempotency_key = concat('reverse:', p.id)) as reversed
from point_ledger p
where p.student_id = #{studentId}
order by p.id desc
limit #{size} offset #{offset}

select id, student_id, amount, category, reason, idempotency_key
from point_ledger
where idempotency_key = #{idempotencyKey}

select id, student_id, amount, category, reason, idempotency_key
from point_ledger
where id = #{id}
